#!/usr/bin/env python3
"""Execute legacy128-bit PSRLDQ through Rosetta, all byte pairs per lane."""
import hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];out=R/'generated/sse/legacy-shiftrbytes-reference';out.mkdir(exist_ok=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();source=R/'tests/legacy_shiftrbytes_oracle.c';table=out/'shifts.inc';table.write_text(''.join('case '+str(i)+':RUN("psrldq $'+str(i)+', %%xmm1");break;\n' for i in range(256)));exe=out/'reference';sdk=subprocess.check_output(['xcrun','--sdk','macosx','--show-sdk-path'],text=True).strip();cmd=['clang','-target','x86_64-apple-macos12','-isysroot',sdk,'-std=c11','-O2','-mavx','-mno-red-zone','-Wall','-Wextra','-Werror','-I',str(out),str(source),'-o',str(exe)];subprocess.run(cmd,check=True);run=subprocess.run([str(exe)],capture_output=True,text=True,timeout=60);assert not run.returncode and run.stdout.startswith('PASS:') and not run.stderr,(run.returncode,run.stdout,run.stderr);(out/'run.log').write_text(run.stdout);assembly=subprocess.check_output(['otool','-tvV',str(exe)],text=True);(out/'disassembly.txt').write_text(assembly);assert assembly.count('\tpsrldq\t')==256 and 'vpsrldq' not in assembly;report={'pass':True,'cases':65536,'source_sha256':{str(p.relative_to(R)):sha(p) for p in [source,pathlib.Path(__file__).resolve(),table]},'binary_sha256':sha(exe),'compile_command':cmd,'output':run.stdout.strip(),'scope':'Canonical legacy PSRLDQ all256 immediate counts, 128 bitbasis and128 deterministic samples per count. XMMshift/zero result, upperYMM/source preservation, all1024 maskedMXCSR configs and arithmeticflag patterns. Rosetta reference, not physicalIntel/unmasked guest/fullDLL/gameplay proof.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(run.stdout.strip())
